(7640038, 1240547, 67258, '<td valign="top">Cool portrait, but a tad over-sharpened - there are some noticeable artefacts and haloing.</td>', 'Cool portrait, but a tad over-sharpened - there are some noticeable artefacts and haloing.', '2019-09-01 05:56:36.000000', NULL, 1),
(7640039, 1239956, 67258, '<td valign="top">Good composition and interesting feature, but a little over-sharpened - there are some noticeable artefacts and haloing.</td>', 'Good composition and interesting feature, but a little over-sharpened - there are some noticeable artefacts and haloing.', '2019-09-01 05:57:28.000000', NULL, 1),
(7640040, 1240351, 67258, '<td valign="top">Very pretty and serene.  Just what I need this morning :)</td>', 'Very pretty and serene.  Just what I need this morning :)', '2019-09-01 05:57:53.000000', NULL, 1),
(7640042, 1240433, 67258, '<td valign="top">Probably the best of its kind that I have ever viewed.  Straight ten without a doubt.</td>', 'Probably the best of its kind that I have ever viewed.  Straight ten without a doubt.', '2019-09-01 06:02:33.000000', NULL, 1),
(7640044, 1240213, 67258, '<td valign="top">A beautifully understated coastal landscape.  This photo does require the viewer to spend time with it, so may not fare as well as it deserves in competition.</td>', 'A beautifully understated coastal landscape.  This photo does require the viewer to spend time with it, so may not fare as well as it deserves in competition.', '2019-09-01 06:03:45.000000', NULL, 1),
(7640045, 1240417, 67258, '<td valign="top">Fabulous atmospheric perspective, layered look.</td>', 'Fabulous atmospheric perspective, layered look.', '2019-09-01 06:04:50.000000', NULL, 1),
(7640047, 1240531, 67258, '<td valign="top">A good composition and an appealing subject and idea, but not quite crisp enough in the focus to really carry it off to full effect.</td>', 'A good composition and an appealing subject and idea, but not quite crisp enough in the focus to really carry it off to full effect.', '2019-09-01 06:06:34.000000', NULL, 1),
(7640049, 1240293, 114285, '<td valign="top">Sweet boy.</td>', 'Sweet boy.', '2019-09-01 06:20:33.000000', NULL, 1),
(7640053, 1240435, 67258, '<td valign="top">What a fabulous landscape - and the eye is led around it perfectly.</td>', 'What a fabulous landscape - and the eye is led around it perfectly.', '2019-09-01 06:34:24.000000', NULL, 1),
(7640054, 1240304, 67258, '<td valign="top">Delightfully delicate.</td>', 'Delightfully delicate.', '2019-09-01 06:35:06.000000', NULL, 1),
(7640055, 1240005, 67258, '<td valign="top">I do admire this photo, but rather wish that you hadn''t framed so tightly.  I would love it more if the humming bird were smaller in the frame.  The level of detail is really good - particularly on the plumage of the far wing.</td>', 'I do admire this photo, but rather wish that you hadn''t framed so tightly.  I would love it more if the humming bird were smaller in the frame.  The level of detail is really good - particularly on the plumage of the far wing.', '2019-09-01 06:35:32.000000', NULL, 1),
(7640056, 1240521, 67258, '<td valign="top">Thoroughly impressive.</td>', 'Thoroughly impressive.', '2019-09-01 06:37:22.000000', NULL, 1),
(7640057, 1240539, 67258, '<td valign="top">A beautifully delicate and summer-filled photo.</td>', 'A beautifully delicate and summer-filled photo.', '2019-09-01 06:37:47.000000', NULL, 1),
(7640058, 1240520, 67258, '<td valign="top">His secret world.  A super study.</td>', 'His secret world.  A super study.', '2019-09-01 06:38:20.000000', NULL, 1),
